    },
    {
      "id": "CQ-005",
      "topic": "Multi-Tenancy and Brand Authentication",
      "question": "How are Brand and Creator identities verified across service boundaries?",
      "impact": "Determines auth middleware implementation.",
      "default_assumption_v1": "Stateless JWT tokens issued by User Service, signed using RS256. `campaign-service` verifies tokens locally using User Service's cached public key (JWKS). Claims include `user_id`, `role` (`brand` | `creator` | `admin`), and tenant identifier.",
      "rationale": "Zero inter-service HTTP overhead on critical read/write paths."
    }
  ],
  "user_stories": [
    {
      "id": "US-001",
      "title": "Create Draft Campaign",
      "priority": "P0",
      "actor": "Brand User",
      "narrative": "As a Brand, I want to create and incrementally save a campaign brief with budget and eligibility rules as a draft, so that I can prepare my campaign without publishing prematurely.",
      "acceptance_criteria": [
        {
          "scenario": "Successful Draft Creation with Minimal Fields",
          "given": "An authenticated user with role 'brand'",
          "when": "A POST request is sent to '/v1/campaigns' with a valid title and brief description",
          "then": "A campaign record is created in PostgreSQL with status 'DRAFT', a generated UUID, created_at timestamp, and owner_id matching the authenticated user; returns HTTP 201 Created."
        },
        {
          "scenario": "Partial Updates to Existing Draft",
          "given": "A campaign in 'DRAFT' status owned by the authenticated brand",
          "when": "A PATCH request is sent to '/v1/campaigns/{id}' with updated budget and eligibility parameters",
          "then": "The draft fields are updated, 'updated_at' is refreshed, status remains 'DRAFT', and HTTP 200 OK is returned."
        },
        {
          "scenario": "Unauthorized Brand Access",
          "given": "A campaign owned by Brand A",
          "when": "Brand B attempts to modify Brand A's draft via PATCH '/v1/campaigns/{id}'",
          "then": "The service rejects the request and returns HTTP 403 Forbidden without modifying data."
        }
      ]
    },
    {
      "id": "US-002",
      "title": "Define Campaign Budget and Compensation Model",
      "priority": "P0",
      "actor": "Brand User",
