          "scenario": "Valid Budget Configuration",
          "given": "A campaign in 'DRAFT' status",
          "when": "The brand sets 'total_budget_cents' to 500000 ($5,000.00), 'payout_per_creator_cents' to 50000 ($500.00), and currency to 'USD'",
          "then": "The database persists these values, validating that 'payout_per_creator_cents' <= 'total_budget_cents' and both values are positive integers."
        },
        {
          "scenario": "Invalid Budget Rejection",
          "given": "A campaign in 'DRAFT' status",
          "when": "The brand attempts to set a negative budget or a 'payout_per_creator_cents' greater than 'total_budget_cents'",
