      ]
    },
    {
      "id": "US-003",
      "title": "Define Creator Eligibility Criteria",
      "priority": "P0",
      "actor": "Brand User",
      "narrative": "As a Brand, I want to specify creator eligibility criteria (niche/category, minimum follower count, geographic regions), so that only relevant creators apply.",
      "acceptance_criteria": [
        {
          "scenario": "Persisting Structured Criteria",
