          "then": "The eligibility object is validated against the Pydantic schema and stored in a PostgreSQL JSONB column with GIN index compatibility."
        },
        {
          "scenario": "Rejecting Unrecognized Country Codes or Malformed Schemas",
          "given": "A campaign in 'DRAFT' status",
          "when": "The brand submits an invalid ISO country code or negative follower threshold",
          "then": "The request is rejected with HTTP 422 and clear schema validation feedback."
        }
      ]
    },
    {
      "id": "US-004",
      "title": "Publish Campaign to Marketplace",
      "priority": "P0",
      "actor": "Brand User",
      "narrative": "As a Brand, I want to transition my draft campaign to published status, so that it becomes immediately visible to creators in the marketplace.",
      "acceptance_criteria": [
        {
          "scenario": "Successful Publication with All Guards Satisfied",
          "given": "A 'DRAFT' campaign containing title, brief, budget, valid eligibility criteria, and an end_date at least 24 hours in the future",
          "when": "The brand calls POST '/v1/campaigns/{id}/publish'",
          "then": "State transitions to 'ACTIVE', 'published_at' is recorded, an asynchronous Celery task is dispatched for auto-expiry, related Redis cache keys are invalidated, and HTTP 200 OK is returned."
        },
        {
          "scenario": "Publishing Incomplete Draft",
          "given": "A 'DRAFT' campaign missing budget or end_date",
          "when": "The brand calls POST '/v1/campaigns/{id}/publish'",
          "then": "Transition is blocked, state remains 'DRAFT', and HTTP 400 Bad Request is returned listing the missing mandatory publish requirements."
        }
      ]
    },
    {
      "id": "US-005",
      "title": "Browse Active Marketplace Campaigns",
      "priority": "P0",
      "actor": "Creator User",
      "narrative": "As a Creator, I want to browse a paginated, filterable feed of active campaigns, so that I can discover collaboration opportunities.",
      "acceptance_criteria": [
        {
          "scenario": "Marketplace Feed Retrieval with Cursor Pagination",
          "given": "100 active campaigns exist in the database",
          "when": "A creator calls GET '/v1/marketplace/campaigns?limit=20'",
          "then": "The service returns an array of 20 campaigns in 'ACTIVE' state, sorted by 'published_at' DESC, along with a 'next_cursor' token."
        },
        {
          "scenario": "Filter by Category and Compensation",
          "given": "Multiple active campaigns across different niches",
          "when": "A creator requests GET '/v1/marketplace/campaigns?category=Tech&min_payout_cents=30000'",
          "then": "Only active campaigns matching category 'Tech' and offering >= $300 payout are returned."
        },
        {
          "scenario": "Draft and Paused Campaigns Excluded",
          "given": "Campaigns exist in 'DRAFT', 'PAUSED', 'COMPLETED', and 'CANCELLED' states",
          "when": "Any user queries the marketplace feed",
          "then": "Non-active campaigns are strictly omitted from the response."
        }
      ]
    },
    {
      "id": "US-006",
      "title": "View Detailed Campaign Brief and Eligibility Check",
      "priority": "P0",
      "actor": "Creator User",
      "narrative": "As a Creator, I want to inspect a campaign's complete brief and immediately see if my profile meets the brand's eligibility requirements.",
      "acceptance_criteria": [
        {
          "scenario": "Eligible Creator Views Active Campaign",
          "given": "An active campaign requiring US creators with >= 10,000 followers, and an authenticated creator possessing 15,000 followers in the US",
          "when": "The creator sends GET '/v1/marketplace/campaigns/{id}'",
          "then": "Full campaign details are returned along with an eligibility payload: '{ \"is_eligible\": true, \"unmet_criteria\": [] }'."
        },
        {
          "scenario": "Ineligible Creator Views Active Campaign",
          "given": "An active campaign requiring 50,000 followers, and a creator with 10,000 followers",
          "when": "The creator sends GET '/v1/marketplace/campaigns/{id}'",
          "then": "Full campaign details are returned along with: '{ \"is_eligible\": false, \"unmet_criteria\": [\"MIN_FOLLOWERS_NOT_MET\"] }'."
        }
      ]
    },
    {
      "id": "US-007",
      "title": "Pause and Resume Active Campaign",
      "priority": "P1",
      "actor": "Brand User",
      "narrative": "As a Brand, I want to temporarily pause an active campaign, so that creators cannot apply while I review existing submissions.",
      "acceptance_criteria": [
        {
          "scenario": "Brand Pauses Active Campaign",
          "given": "A campaign in 'ACTIVE' status",
          "when": "The brand calls POST '/v1/campaigns/{id}/pause'",
          "then": "Status transitions to 'PAUSED', marketplace cache is invalidated, and the campaign is hidden from the public marketplace feed."
        },
        {
          "scenario": "Brand Resumes Paused Campaign",
          "given": "A campaign in 'PAUSED' status with an end_date in the future",
          "when": "The brand calls POST '/v1/campaigns/{id}/resume'",
          "then": "Status transitions back to 'ACTIVE', campaign reappears in the marketplace feed, and HTTP 200 OK is returned."
        }
      ]
    },
    {
      "id": "US-008",
      "title": "Automated Campaign Expiration",
      "priority": "P0",
      "actor": "System (Celery Scheduler)",
      "narrative": "As the Platform, I want campaigns to automatically expire when their end date passes, so that outdated briefs do not clutter the marketplace.",
      "acceptance_criteria": [
        {
          "scenario": "Scheduled Expiration Trigger",
          "given": "An 'ACTIVE' campaign whose 'end_date' has arrived",
          "when": "The Celery Beat recurring worker executes the 'expire_outdated_campaigns' batch task",
          "then": "Campaign status transitions atomically to 'COMPLETED', marketplace cache is evicted, and an audit log event 'campaign.expired' is recorded."
        }
      ]
    },
    {
      "id": "US-009",
      "title": "Cancel Campaign",
      "priority": "P1",
      "actor": "Brand User",
      "narrative": "As a Brand, I want to permanently cancel a campaign, so that no further applications or interactions occur.",
      "acceptance_criteria": [
        {
          "scenario": "Cancel from DRAFT, ACTIVE, or PAUSED",
          "given": "A campaign owned by the brand in 'DRAFT', 'ACTIVE', or 'PAUSED' state",
          "when": "The brand sends POST '/v1/campaigns/{id}/cancel' with a cancellation reason",
          "then": "Status transitions to 'CANCELLED', scheduled Celery jobs are cancelled, marketplace cache is invalidated, and campaign can no longer be resumed."
        },
        {
          "scenario": "Attempting to Cancel Already Completed Campaign",
          "given": "A campaign in 'COMPLETED' state",
          "when": "The brand sends POST '/v1/campaigns/{id}/cancel'",
          "then": "The transition is rejected with HTTP 409 Conflict."
        }
      ]
    }
  ],
  "state_machine": {
    "entity": "Campaign",
    "initial_state": "DRAFT",
    "terminal_states": ["COMPLETED", "CANCELLED"],
    "states": [
      {
        "name": "DRAFT",
        "description": "Initial state. Fully editable by the owner brand; completely hidden from creators and marketplace."
      },
      {
        "name": "ACTIVE",
        "description": "Publicly published. Visible in the marketplace feed; eligible creators can view brief and prepare applications."
      },
      {
        "name": "PAUSED",
        "description": "Temporarily disabled by brand. Hidden from public marketplace feed; no new submissions allowed."
      },
      {
        "name": "COMPLETED",
        "description": "Naturally expired because 'end_date' was reached or total budget exhausted. Read-only historical record."
      },
      {
        "name": "CANCELLED",
        "description": "Terminated prematurely by the brand. Terminal read-only state."
      }
    ],
    "transitions": [
      {
        "from_state": "DRAFT",
        "to_state": "ACTIVE",
        "action": "publish",
        "authorized_roles": ["brand", "admin"],
        "guards": [
          "caller_is_owner",
          "title_is_not_empty",
          "brief_description_min_length_50_chars",
          "total_budget_cents > 0",
          "payout_per_creator_cents > 0",
          "payout_per_creator_cents <= total_budget_cents",
          "end_date_is_at_least_24h_in_future",
          "eligibility_criteria_is_valid_schema"
        ],
        "side_effects": [
          "Set published_at = NOW()",
          "Invalidate Redis marketplace cache tags",
          "Dispatch Celery delayed task 'campaign_auto_expire' scheduled for end_date",
          "Emit domain event 'campaign.published'"
        ]
      },
      {
        "from_state": "ACTIVE",
        "to_state": "PAUSED",
        "action": "pause",
        "authorized_roles": ["brand", "admin"],
        "guards": [
          "caller_is_owner"
        ],
        "side_effects": [
          "Set paused_at = NOW()",
          "Invalidate Redis marketplace cache",
          "Emit domain event 'campaign.paused'"
        ]
      },
      {
        "from_state": "PAUSED",
        "to_state": "ACTIVE",
        "action": "resume",
        "authorized_roles": ["brand", "admin"],
        "guards": [
          "caller_is_owner",
          "end_date_is_in_future"
        ],
        "side_effects": [
          "Set resumed_at = NOW()",
          "Invalidate Redis marketplace cache",
          "Reschedule Celery auto-expiry if end_date was modified",
          "Emit domain event 'campaign.resumed'"
        ]
      },
      {
        "from_state": "ACTIVE",
        "to_state": "COMPLETED",
        "action": "expire",
        "authorized_roles": ["system_worker", "admin"],
