        "side_effects": [
          "Set completed_at = NOW()",
          "Invalidate Redis marketplace cache",
          "Emit domain event 'campaign.completed'"
        ]
      },
      {
        "from_state": "PAUSED",
        "to_state": "COMPLETED",
        "action": "expire",
        "authorized_roles": ["system_worker", "admin"],
        "guards": [
          "current_time >= end_date"
        ],
        "side_effects": [
          "Set completed_at = NOW()",
          "Emit domain event 'campaign.completed'"
        ]
      },
      {
        "from_state": "DRAFT",
        "to_state": "CANCELLED",
        "action": "cancel",
        "authorized_roles": ["brand", "admin"],
        "guards": [
          "caller_is_owner"
        ],
        "side_effects": [
          "Set cancelled_at = NOW()",
          "Emit domain event 'campaign.cancelled'"
        ]
      },
      {
        "from_state": "ACTIVE",
        "to_state": "CANCELLED",
        "action": "cancel",
        "authorized_roles": ["brand", "admin"],
        "guards": [
          "caller_is_owner"
        ],
        "side_effects": [
          "Set cancelled_at = NOW()",
          "Revoke scheduled Celery expiry task",
          "Invalidate Redis marketplace cache",
          "Emit domain event 'campaign.cancelled'"
        ]
      },
      {
        "from_state": "PAUSED",
        "to_state": "CANCELLED",
        "action": "cancel",
        "authorized_roles": ["brand", "admin"],
        "guards": [
          "caller_is_owner"
        ],
        "side_effects": [
          "Set cancelled_at = NOW()",
          "Revoke scheduled Celery expiry task",
          "Emit domain event 'campaign.cancelled'"
        ]
      }
