  "edge_cases": [
    {
      "id": "EC-001",
      "category": "Concurrency & State Conflicts",
      "scenario": "Brand attempts double-publish or concurrent updates from multiple browser tabs simultaneously.",
      "handling_strategy": "Implement Optimistic Concurrency Control (OCC) using an integer 'version' column in the PostgreSQL 'campaigns' table. Update queries execute with 'WHERE id = :id AND version = :expected_version'. If rows affected == 0, raise HTTP 409 Conflict. In addition, API state transitions use Redis distributed lock (Redlock pattern) keyed by 'lock:campaign:{id}' for a 5-second lease during transition execution.",
      "severity": "High"
    },
    {
      "id": "EC-002",
      "category": "Time & Scheduling",
      "scenario": "Brand sets 'end_date' precisely as the system clock transitions or sets an end_date in the past due to client-server clock skew.",
      "handling_strategy": "Enforce UTC standardization system-wide. Pydantic validator requires 'end_date >= datetime.now(timezone.utc) + timedelta(hours=24)'. Celery Beat runs a fallback reconciler every 10 minutes querying 'SELECT id FROM campaigns WHERE status = 'ACTIVE' AND end_date <= NOW()' to catch any missed Celery event timers.",
      "severity": "Medium"
    },
    {
      "id": "EC-003",
      "category": "Cache Consistency & Stampede",
      "scenario": "A high-profile campaign is published or paused, causing millions of creators to refresh the marketplace feed simultaneously when cache expires.",
      "handling_strategy": "Marketplace list caching employs Redis with Probabilistic Early Expiration (XFetch algorithm) and jittered TTL (e.g., 300s +/- 30s). Cache invalidation publishes to a Redis Pub/Sub topic which flushes local application L1 caches (if any) and evicts primary marketplace keys.",
      "severity": "High"
