    {
      "id": "EC-005",
      "category": "Downstream Service Failure",
      "scenario": "User Service is down or experiencing high latency when a creator views a campaign brief.",
      "handling_strategy": "Do not fail the campaign retrieval. The core campaign brief is loaded from campaign-service DB/cache. For the eligibility check, if User Service profile call fails, gracefully return campaign details with 'eligibility_status': 'INDETERMINATE' and a degraded flag rather than HTTP 500.",
      "severity": "Medium"
    },
    {
      "id": "EC-006",
      "category": "Content Security & XSS",
      "scenario": "Brand submits malicious HTML/JavaScript tags inside the markdown brief description.",
