      "severity": "High"
    },
    {
      "id": "EC-007",
      "category": "Deep Pagination Exhaustion",
      "scenario": "A bot or scraper requests page 10,000 using 'OFFSET 100000', exhausting database memory and CPU.",
      "handling_strategy": "Prohibit OFFSET-based pagination. Enforce Keyset/Cursor-based pagination using '(published_at, id)' composites with an opaque base64-encoded cursor token. Enforce maximum 'limit=50'.",
      "severity": "Medium"
